// 指向 Honey 对象 H 的 12 根引用（main 结束前）：
// 1) honeyPot
// 2-5) ha[0] ha[1] ha[2] ha[3]         ← 数组每个元素各算一根
// 6-10) bears[0..4].hunny              ← 循环五只熊各有引用
// 11) kit.honey（kit=null 后仍作为 raccoon.rk.honey 存在）← 最易漏
// 12) raccoon.rh
//
// 注意：bees.beeHoney 指向的是数组 ha，raccoon.rk 指向 Kit 对象，
//       它们是通往 H 的路径中转，不是直接引用 H，不计入 12 根。

public abstract class Animal {
    private String name;                     // private：子类不可直接访问
    public String getName() { return name; } // 但子类继承了读取它的方法
    public Animal(String theName) {          // 只有带参构造器，没有无参版本
        name = theName;
    }
}
public class Hippo extends Animal {
    public Hippo(String name) {
        super(name);                         // 必须显式传值，否则编译器补 super() 会失败
    }
}
public class MakeHippo {
    public static void main(String[] args) {
        Hippo h = new Hippo("Buffy");
        System.out.println(h.getName());     // 输出 Buffy
    }
}

